def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("889.d.17.A",3,"A mechanic pulls a spark plug, cleans the electrodes, checks the gap and torques it back in. She is:","removing, cleaning, inspecting and installing a spark plug",["painting a spark plug","ignoring a spark plug","buying a spark plug"],"Plug service.")
H("889.d.17.A",4,"Before reinstalling a cleaned spark plug, the mechanic should verify the:","electrode gap",["paint color","seat fit","tire size"],"Gap check.")
H("889.d.17.B",3,"A mechanic checks the battery, cables, starter switch and starter relay of an engine start circuit. She is:","inspecting an electrical starting system",["ignoring the starter","painting the starter","guessing"],"Starter inspection.")
H("889.d.17.B",4,"During a starting system inspection, loose or corroded cable ends should be:","cleaned and tightened",["painted","ignored","greased only"],"Cable ends.")
H("889.d.17.C",3,"An engine won't crank, so a mechanic uses a meter to follow voltage from the battery to the starter. She is:","troubleshooting an electrical starting system",["ignoring the starter","painting cables","guessing"],"Starter trouble.")
H("889.d.17.C",4,"If the starter solenoid clicks but the starter doesn't turn, a good first check is the:","battery voltage under load",["tire pressure","oil color","seat track"],"Under load.")
H("889.d.17.D",3,"The engine won't shut off with the key because the magneto switch circuit is faulty, so the mechanic tests the switch and the P-lead. She is:","troubleshooting an ignition switch circuit",["ignoring the switch","painting the switch","guessing"],"Switch circuit.")
H("889.d.17.D",4,"An ignition switch that does not ground the P-lead in the OFF position can leave the magneto:","live and able to fire",["safely off","cool","extra quiet"],"Open ground.")
H("889.d.17.E",3,"A mechanic matches an engine's manufacturer chart to the correct spark plug part number and heat range. She is:","identifying the correct spark plugs for replacement installation",["guessing a plug","using any plug","ignoring the chart"],"Plug choice.")
H("889.d.17.E",4,"A spark plug heat range tells how well the plug:","carries heat away from its tip",["holds fuel","looks","sounds"],"Heat range.")
H("889.d.17.F",3,"A mechanic checks the turbine engine parts list to pick the right igniter plug for a combustor. She is:","identifying the correct igniter plug on a turbine engine",["guessing","using a spark plug","ignoring the list"],"Igniter plug.")
H("889.d.17.F",4,"A turbine igniter plug differs from a piston spark plug because it:","has a surface-discharge design built for high energy",["has no electrode","needs no wire","uses oil"],"Igniter design.")
H("889.d.18.A",3,"A student studies why too much fuel makes black smoke and too little makes a lean, hot engine. She is explaining:","the purpose of proper fuel to air ratios and fuel metering",["ignoring ratios","describing seats","describing tires"],"Fuel-air ratio.")
H("889.d.18.A",4,"A lean mixture can cause an engine to:","run hot and risk detonation",["run cold","make more oil","never start"],"Lean risk.")
H("889.d.18.B",3,"A student labels the throttle body, mixture control and metering jets of a fuel metering system. She is:","identifying the components, basic operation and adjustment of fuel metering systems",["labeling seats","labeling tires","labeling lights"],"Metering system.")
H("889.d.18.B",4,"Moving the mixture control toward lean:","reduces the fuel flow for the air entering the engine",["adds fuel","adds air","stops the pump"],"Mixture control.")
H("889.d.18.C",3,"A student traces fuel from the tank through a heater, lines, a pump, a valve and a filter. She is explaining:","the purpose and basic operation of fuel heaters, lines, pumps, valves and filters",["avoiding fuel","describing seats","describing tires"],"Fuel path.")
H("889.d.18.C",4,"A fuel heater on a turbine engine keeps:","ice crystals from clogging the fuel filter",["fuel hot for burning","the tank full","the pump quiet"],"Fuel heater.")
H("889.d.18.D",3,"A student explains how a nozzle sprays fuel in a fine mist and how a manifold feeds the nozzles. She is explaining:","the basic operation of fuel nozzles and manifolds",["ignoring nozzles","describing seats","describing tires"],"Nozzles.")
H("889.d.18.D",4,"A fuel nozzle sprays fuel in a fine mist so that it:","burns completely with the air",["pools","freezes","leaks"],"Spray pattern.")
H("889.d.18.E",3,"A student labels the fuel control, flow divider and nozzles of a turbine engine's fuel system. She is:","identifying the components and explaining the basic operation of turbine engine fuel metering systems",["labeling seats","labeling tires","labeling lights"],"Turbine fuel.")
H("889.d.18.E",4,"A turbine fuel control automatically adjusts fuel flow based on:","power lever setting, rpm and air conditions",["tire wear","seat weight","paint"],"Fuel control inputs.")
H("889.d.18.F",3,"A mechanic opens the manual to the checklist for engine fuel system inspections at each service interval. She is:","locating and explaining inspection requirements for an engine fuel system",["guessing","ignoring the manual","painting lines"],"Inspection reqs.")
H("889.d.18.F",4,"A fuel system inspection looks for:","leaks, chafing, loose fittings and clogged filters",["tire wear","seat cracks","paint chips"],"Inspect for leaks.")
H("889.d.18.G",3,"A student describes how fuel moves from the tank to the cylinders when the engine runs. She is:","explaining fuel system operation",["ignoring fuel","describing seats","describing tires"],"Fuel operation.")
H("889.d.18.G",4,"An engine-driven fuel pump usually supplies fuel:","at a higher pressure than the boost pump",["at zero pressure","with no flow","only at idle"],"Pump pressure.")
H("889.d.18.H",3,"A student reads that a wrong adjustment of a turbine fuel control can cause an overtemp or overspeed. She is researching:","the risks of adjusting turbine engine fuel controls",["no risks","paint choices","tire brands"],"Turbine FCU risk.")
H("889.d.18.H",4,"Adjusting a turbine fuel control without the manual's limits could cause:","an overtemperature or overspeed",["better economy","a cooler engine","less wear"],"Overtemp.")
H("889.d.18.I",3,"A student reads that setting a piston engine's mixture too lean can damage the cylinders. She is researching:","the risks of adjusting reciprocating engine fuel controls",["no risks","paint choices","tire brands"],"Piston FCU risk.")
H("889.d.18.I",4,"An incorrect lean adjustment on a piston engine could cause:","burned valves or pistons",["a cleaner engine","a cooler engine","a quieter engine"],"Burned parts.")
H("889.d.18.J",3,"A mechanic is told that fuel on the skin or in the air is a fire and health hazard when handling fuel metering parts. She is researching:","the risks of handling fuel metering system components or fuel",["no risks","paint choices","tire brands"],"Handling fuel.")
H("889.d.18.J",4,"When handling fuel components, a mechanic should work:","in a ventilated area away from ignition sources",["near sparks","in a closed room","near open flames"],"Ventilation.")
H("889.d.18.K",3,"A student reads that opening fuel lines on a tank can spill fuel and release vapors. She is researching:","the risks of fuel system maintenance",["no risks","paint choices","tire brands"],"Fuel maintenance.")
H("889.d.18.K",4,"Before opening a fuel line, a mechanic should:","depressurize and drain the line and have a fire extinguisher ready",["leave it live","smoke nearby","ignore spills"],"Prep.")
H("889.d.19.A",3,"A student labels the float bowl, venturi, throttle plate and main jet of a carburetor. She is:","identifying carburetor components",["labeling seats","labeling tires","labeling lights"],"Carb parts.")
H("889.d.19.A",4,"The venturi in a carburetor creates:","low pressure that draws in fuel",["high pressure","heat","oil"],"Venturi.")
H("889.d.19.B",3,"A student draws arrows to show fuel rising from the float bowl and mixing with the air in the venturi. She is:","identifying fuel and air flow through a float-type carburetor",["ignoring flow","describing seats","describing tires"],"Carb flow.")
H("889.d.19.B",4,"In a float-type carburetor, the float and needle valve keep the bowl at a:","constant fuel level",["changing level","zero level","random level"],"Float level.")
H("889.d.19.C",3,"A mechanic unscrews the main metering jet from a carburetor, cleans it and replaces it. She is:","removing and installing a carburetor main metering jet",["painting a jet","ignoring a jet","buying a jet"],"Main jet.")
