H("889.d.19.D",4,"A float level set too high can lead to:","a rich mixture or fuel leakage",["a lean mixture","low flow","cold running"],"Float high.")
H("889.d.19.E",3,"A mechanic turns the idle stop screw and mixture screw until the engine idles smoothly at the correct rpm. She is:","adjusting carburetor idle speed and mixture",["ignoring idle","painting screws","guessing"],"Idle adjust.")
H("889.d.19.E",4,"The idle mixture is often set by finding the setting that gives:","a slight rpm rise as the mixture is leaned (peak rpm)",["lowest rpm","stalling","maximum fuel"],"Peak rpm.")
H("889.d.19.F",3,"A mechanic opens the manual to the steps for handling a turbine engine overspeed event. She is:","researching and locating procedures for a turbine engine rpm overspeed",["ignoring overspeed","guessing","painting the tach"],"Overspeed.")
H("889.d.19.F",4,"After an engine overspeed, the engine usually needs:","an inspection per the manual before further flight",["no checks","a repaint","a new tire"],"Overspeed check.")
H("889.d.19.G",3,"A mechanic follows the manual's steps to adjust a hydromechanical fuel control unit for idle and max rpm. She is:","researching and locating procedures for adjusting a hydromechanical fuel control unit",["guessing","ignoring the manual","painting the FCU"],"Hydro FCU.")
